  PresenceService --> DevicePresence : refreshes TTL
  PresenceService --> UserAggregate : derives OR
  Gateway --> PresenceService : forwards

public class PresenceService {
    private final RedisCluster redis; // JedisCluster / Lettuce
    private final EventLog log;       // Kafka producer
    private static final int TTL_SEC = 45;

    public void heartbeat(String userId, String deviceId, long ts) {
        String dKey = "d:" + userId + ":" + deviceId;
        String uKey = "u:" + userId;
        // 1. Refresh ephemeral device liveness. Idempotent, last-write-wins.
        redis.setex(dKey, TTL_SEC, String.valueOf(ts));
        // 2. Derive user aggregate. SET if first device, refresh otherwise.
        // Lua keeps check-and-set atomic without a lock.
        boolean flippedToOnline = redis.evalFlipOnline(uKey, TTL_SEC);
        if (flippedToOnline) {
            log.publish("presence-events", userId,
                new StatusEvent(userId, true, ts));
        }
    }

    // Called by Redis keyspace notification on device-key expiry.
    public void onDeviceExpire(String userId, long now) {
        // Re-check: any surviving device key? If none, flip to offline.
        if (!redis.existsByPattern("d:" + userId + ":*")) {
            redis.del("u:" + userId);
            log.publish("presence-events", userId,
                new StatusEvent(userId, false, now));
            durableLastSeen.write(userId, now); // async, off critical path
        }
    }

    public Map<String, String> getBulk(List<String> userIds) {
        // One pipelined round-trip, not N round-trips. This is the login path.
        return redis.mget(userIds.stream()
            .map(id -> "u:" + id).toList());
    }
}
